css:
[data-bz-node="bb"] { position: relative; z-index: 5; filter: drop-shadow(0 18px 30px rgba(0,0,0,.65)); }
[data-bz-node="bb-band"] { display: block; position: relative; width: 104%; margin-left: -2%; transform: rotate(-2deg); overflow: hidden; background: #0b3d4b;
  clip-path: polygon(0% 7%, 3% 2%, 6% 6%, 9% 1%, 12% 5%, 15% 0%, 19% 6%, 22% 2%, 26% 7%, 29% 1%, 33% 5%, 36% 0%, 40% 6%, 43% 2%, 47% 7%, 50% 1%, 54% 5%, 57% 0%, 61% 6%, 64% 2%, 68% 7%, 71% 1%, 75% 5%, 78% 0%, 82% 6%, 85% 2%, 89% 7%, 92% 1%, 96% 5%, 100% 2%, 100% 95%, 97% 99%, 93% 94%, 90% 100%, 86% 95%, 83% 99%, 79% 93%, 76% 98%, 72% 94%, 69% 100%, 65% 95%, 62% 99%, 58% 93%, 55% 98%, 51% 94%, 48% 100%, 44% 95%, 41% 99%, 37% 93%, 34% 98%, 30% 94%, 27% 100%, 23% 95%, 20% 99%, 16% 93%, 13% 98%, 9% 94%, 6% 100%, 3% 95%, 0% 99%); }
[data-bz-node="bb-band"]::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(2,6,23,.92) 0%, rgba(2,6,23,.7) 40%, rgba(2,6,23,0) 65%); pointer-events: none; z-index: 1; }
[data-bz-node="bb-art"] { position: absolute; top: -40px; right: 6%; width: 440px; max-width: 60%; z-index: 0; }
[data-bz-node="bb-art"] img { width: 100%; height: auto; border-radius: 0; }
[data-bz-node="bb-copy"] { position: relative; z-index: 2; min-height: 300px; padding: 70px 40px 70px clamp(40px, 7vw, 120px); display: flex; flex-direction: column; align-items: flex-start; justify-content: center; gap: 18px; text-align: left; }
[data-bz-node="bb-title"].bz-block p { margin: 0; max-width: 620px; font-family: 'Orbitron', var(--font-heading), sans-serif; font-weight: 900; font-size: clamp(30px, 5vw, 68px); line-height: 1; letter-spacing: .06em; text-transform: uppercase; color: #f4fbff; text-shadow: 0 4px 24px rgba(0,0,0,.7); }
[data-bz-node="bb-tag"].bz-block p { margin: 0; font-family: 'Orbitron', var(--font-heading), sans-serif; font-weight: 900; font-size: clamp(18px, 2.4vw, 30px); letter-spacing: .18em; text-transform: uppercase; color: #fff; background: #e0112b; padding: 10px 18px; transform: rotate(-3deg); display: inline-block; }
@media (max-width: 640px) { [data-bz-node="bb-copy"] { padding: 60px 24px; } [data-bz-node="bb-art"] { right: -10%; opacity: .6; } }
